-- CODE-COUPLED: keep pending until matching split controller/spell guards
-- are in the promoted executable. No live updater before that promotion.
SET @split_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
SET @split_graph=(SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR),'NULL'),COALESCE(CAST(`source_type` AS CHAR),'NULL'),COALESCE(CAST(`id` AS CHAR),'NULL'),COALESCE(CAST(`link` AS CHAR),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR),'NULL'),COALESCE(CAST(`event_type` AS CHAR),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR),'NULL'),COALESCE(CAST(`event_chance` AS CHAR),'NULL'),COALESCE(CAST(`event_flags` AS CHAR),'NULL'),COALESCE(CAST(`event_param1` AS CHAR),'NULL'),COALESCE(CAST(`event_param2` AS CHAR),'NULL'),COALESCE(CAST(`event_param3` AS CHAR),'NULL'),COALESCE(CAST(`event_param4` AS CHAR),'NULL'),COALESCE(CAST(`event_param5` AS CHAR),'NULL'),COALESCE(CAST(`action_type` AS CHAR),'NULL'),COALESCE(CAST(`action_param1` AS CHAR),'NULL'),COALESCE(CAST(`action_param2` AS CHAR),'NULL'),COALESCE(CAST(`action_param3` AS CHAR),'NULL'),COALESCE(CAST(`action_param4` AS CHAR),'NULL'),COALESCE(CAST(`action_param5` AS CHAR),'NULL'),COALESCE(CAST(`action_param6` AS CHAR),'NULL'),COALESCE(CAST(`target_type` AS CHAR),'NULL'),COALESCE(CAST(`target_param1` AS CHAR),'NULL'),COALESCE(CAST(`target_param2` AS CHAR),'NULL'),COALESCE(CAST(`target_param3` AS CHAR),'NULL'),COALESCE(CAST(`target_param4` AS CHAR),'NULL'),COALESCE(CAST(`target_x` AS CHAR),'NULL'),COALESCE(CAST(`target_y` AS CHAR),'NULL'),COALESCE(CAST(`target_z` AS CHAR),'NULL'),COALESCE(CAST(`target_o` AS CHAR),'NULL'),COALESCE(CAST(`comment` AS CHAR),'NULL')) ORDER BY `entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_x`,`target_y`,`target_z`,`target_o`,`comment` SEPARATOR '\n'),256) FROM smart_scripts WHERE entryorguid=103339 AND source_type=0);
SET @split_actor=(SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entry` AS CHAR),'NULL'),COALESCE(CAST(`gossip_menu_id` AS CHAR),'NULL'),COALESCE(CAST(`minlevel` AS CHAR),'NULL'),COALESCE(CAST(`maxlevel` AS CHAR),'NULL'),COALESCE(CAST(`HealthScalingExpansion` AS CHAR),'NULL'),COALESCE(CAST(`SandboxScalingID` AS CHAR),'NULL'),COALESCE(CAST(`exp` AS CHAR),'NULL'),COALESCE(CAST(`faction` AS CHAR),'NULL'),COALESCE(CAST(`npcflag` AS CHAR),'NULL'),COALESCE(CAST(`npcflag2` AS CHAR),'NULL'),COALESCE(CAST(`speed_walk` AS CHAR),'NULL'),COALESCE(CAST(`speed_run` AS CHAR),'NULL'),COALESCE(CAST(`speed_fly` AS CHAR),'NULL'),COALESCE(CAST(`scale` AS CHAR),'NULL'),COALESCE(CAST(`mindmg` AS CHAR),'NULL'),COALESCE(CAST(`maxdmg` AS CHAR),'NULL'),COALESCE(CAST(`dmgschool` AS CHAR),'NULL'),COALESCE(CAST(`attackpower` AS CHAR),'NULL'),COALESCE(CAST(`dmg_multiplier` AS CHAR),'NULL'),COALESCE(CAST(`baseattacktime` AS CHAR),'NULL'),COALESCE(CAST(`rangeattacktime` AS CHAR),'NULL'),COALESCE(CAST(`unit_class` AS CHAR),'NULL'),COALESCE(CAST(`unit_flags` AS CHAR),'NULL'),COALESCE(CAST(`unit_flags2` AS CHAR),'NULL'),COALESCE(CAST(`unit_flags3` AS CHAR),'NULL'),COALESCE(CAST(`dynamicflags` AS CHAR),'NULL'),COALESCE(CAST(`trainer_type` AS CHAR),'NULL'),COALESCE(CAST(`trainer_spell` AS CHAR),'NULL'),COALESCE(CAST(`trainer_class` AS CHAR),'NULL'),COALESCE(CAST(`trainer_race` AS CHAR),'NULL'),COALESCE(CAST(`minrangedmg` AS CHAR),'NULL'),COALESCE(CAST(`maxrangedmg` AS CHAR),'NULL'),COALESCE(CAST(`rangedattackpower` AS CHAR),'NULL'),COALESCE(CAST(`lootid` AS CHAR),'NULL'),COALESCE(CAST(`pickpocketloot` AS CHAR),'NULL'),COALESCE(CAST(`skinloot` AS CHAR),'NULL'),COALESCE(CAST(`resistance1` AS CHAR),'NULL'),COALESCE(CAST(`resistance2` AS CHAR),'NULL'),COALESCE(CAST(`resistance3` AS CHAR),'NULL'),COALESCE(CAST(`resistance4` AS CHAR),'NULL'),COALESCE(CAST(`resistance5` AS CHAR),'NULL'),COALESCE(CAST(`resistance6` AS CHAR),'NULL'),COALESCE(CAST(`spell1` AS CHAR),'NULL'),COALESCE(CAST(`spell2` AS CHAR),'NULL'),COALESCE(CAST(`spell3` AS CHAR),'NULL'),COALESCE(CAST(`spell4` AS CHAR),'NULL'),COALESCE(CAST(`spell5` AS CHAR),'NULL'),COALESCE(CAST(`spell6` AS CHAR),'NULL'),COALESCE(CAST(`spell7` AS CHAR),'NULL'),COALESCE(CAST(`spell8` AS CHAR),'NULL'),COALESCE(CAST(`PetSpellDataId` AS CHAR),'NULL'),COALESCE(CAST(`VehicleId` AS CHAR),'NULL'),COALESCE(CAST(`mingold` AS CHAR),'NULL'),COALESCE(CAST(`maxgold` AS CHAR),'NULL'),COALESCE(CAST(`AIName` AS CHAR),'NULL'),COALESCE(CAST(`MovementType` AS CHAR),'NULL'),COALESCE(CAST(`HoverHeight` AS CHAR),'NULL'),COALESCE(CAST(`Mana_mod_extra` AS CHAR),'NULL'),COALESCE(CAST(`Armor_mod` AS CHAR),'NULL'),COALESCE(CAST(`RegenHealth` AS CHAR),'NULL'),COALESCE(CAST(`mechanic_immune_mask` AS CHAR),'NULL'),COALESCE(CAST(`flags_extra` AS CHAR),'NULL'),COALESCE(CAST(`ControllerID` AS CHAR),'NULL'),COALESCE(CAST(`WorldEffects` AS CHAR),'NULL'),COALESCE(CAST(`PassiveSpells` AS CHAR),'NULL'),COALESCE(CAST(`StateWorldEffectID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateVisualID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateAnimID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateAnimKitID` AS CHAR),'NULL'),COALESCE(CAST(`IgnoreLos` AS CHAR),'NULL'),COALESCE(CAST(`AffixState` AS CHAR),'NULL'),COALESCE(CAST(`MaxVisible` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL')) ORDER BY `entry`,`gossip_menu_id`,`minlevel`,`maxlevel`,`HealthScalingExpansion`,`SandboxScalingID`,`exp`,`faction`,`npcflag`,`npcflag2`,`speed_walk`,`speed_run`,`speed_fly`,`scale`,`mindmg`,`maxdmg`,`dmgschool`,`attackpower`,`dmg_multiplier`,`baseattacktime`,`rangeattacktime`,`unit_class`,`unit_flags`,`unit_flags2`,`unit_flags3`,`dynamicflags`,`trainer_type`,`trainer_spell`,`trainer_class`,`trainer_race`,`minrangedmg`,`maxrangedmg`,`rangedattackpower`,`lootid`,`pickpocketloot`,`skinloot`,`resistance1`,`resistance2`,`resistance3`,`resistance4`,`resistance5`,`resistance6`,`spell1`,`spell2`,`spell3`,`spell4`,`spell5`,`spell6`,`spell7`,`spell8`,`PetSpellDataId`,`VehicleId`,`mingold`,`maxgold`,`AIName`,`MovementType`,`HoverHeight`,`Mana_mod_extra`,`Armor_mod`,`RegenHealth`,`mechanic_immune_mask`,`flags_extra`,`ControllerID`,`WorldEffects`,`PassiveSpells`,`StateWorldEffectID`,`SpellStateVisualID`,`SpellStateAnimID`,`SpellStateAnimKitID`,`IgnoreLos`,`AffixState`,`MaxVisible`,`ScriptName` SEPARATOR '\n'),256) FROM creature_template WHERE entry IN(103339,104737));
SET @split_old=@split_graph='b8a710830832b1b0e461df13548fc8c7983b7a70079eeb671a26011df2940d24' AND @split_actor='08151ebe1396cfe0c930be66b6a7dcfa9fc8e181c5e43a8f6f2aee9026f7b868' AND (SELECT COUNT(*) FROM spell_script_names WHERE spell_id IN(207244,207249,207258,207275,207297,207299))=0;
SET @split_applied=@split_graph='0f05a67c42264d38044bab10d841aa079042564b106299503d61ed6076113c50' AND @split_actor='176a34e2ca730bbc82fd50b8bb15c416752421d5ca501fa60fb7fe31916179e8' AND (SELECT COUNT(*) FROM spell_script_names WHERE spell_id IN(207244,207249,207258,207275,207297,207299))=6 AND (SELECT COUNT(*) FROM spell_script_names WHERE spell_id IN(207244,207249,207258,207275,207297,207299) AND ScriptName='spell_stromkar_split_transport')=6;
SET @split_safe=(@split_old OR @split_applied) AND (SELECT COUNT(*) FROM creature WHERE id=103339)=1 AND (SELECT COUNT(*) FROM creature WHERE guid=370996 AND id=103339 AND map=1539)=1;
SET @split_guard=IF(COALESCE(@split_safe,0),'DO 0','SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''Stromkar split actor/graph/spell bindings differ; review before promotion''');
PREPARE split_guard FROM @split_guard;EXECUTE split_guard;DEALLOCATE PREPARE split_guard;
UPDATE creature_template SET ScriptName='npc_stromkar_illusionist' WHERE @split_safe AND @split_old AND entry=103339;
UPDATE smart_scripts SET target_type=7,target_param1=0 WHERE @split_safe AND @split_old AND entryorguid=103339 AND source_type=0 AND id=4;
INSERT INTO spell_script_names(spell_id,ScriptName)
SELECT spell_id,'spell_stromkar_split_transport' FROM (
SELECT 207244 AS spell_id UNION ALL SELECT 207249 UNION ALL SELECT 207258 UNION ALL SELECT 207275 UNION ALL SELECT 207297 UNION ALL SELECT 207299
) native_split WHERE @split_safe AND @split_old;
COMMIT;
SET SESSION group_concat_max_len=@split_concat;
